INSERT INTO `r_blok_html` (`adi`, `icerik`, `hash`, `tema`, `sira`, `yayin`) VALUES
('Hero Section', '    <!-- Hero Section -->\n    <section class=\"hero hero-gradient is-medium\">\n        <div class=\"hero-body\">\n            <div class=\"container\">\n                <div class=\"columns is-vcentered\">\n                    <div class=\"column is-7\">\n                        <h1 class=\"title is-1 has-text-white mb-4\">\n                            Transform Your Workflow with <span class=\"has-text-accent\">AI-Powered</span> Intelligence\n                        </h1>\n                        <p class=\"subtitle is-4 has-text-light mb-5\">\n                            NexusAI helps teams and individuals automate tasks, gain insights, and boost productivity by 3x with advanced machine learning algorithms.\n                        </p>\n                        <div class=\"buttons\">\n                            <a id=\"start-free-btn\" class=\"button is-primary is-large has-text-weight-bold\">Start Free Trial</a>\n                            <a id=\"demo-btn\" class=\"button is-light is-large\">Book a Demo</a>\n                        </div>\n                        <p class=\"has-text-light mt-4\">\n                            <i class=\"fas fa-check-circle mr-2\"></i> No credit card required\n                            <i class=\"fas fa-check-circle ml-4 mr-2\"></i> 14-day free trial\n                        </p>\n                    </div>\n                    <div class=\"column is-5\">\n                        <figure class=\"image\">\n                            <img src=\"https://picsum.photos/600/400?random=101\" alt=\"NexusAI dashboard showing analytics and insights\" class=\"is-rounded\" loading=\"lazy\">\n                        </figure>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>', 'hero-section', 'bulma', 100, 1),
('Features Section', '    <!-- Features Section -->\n    <section class=\"section py-6\">\n        <div class=\"container\">\n            <div class=\"has-text-centered mb-6\">\n                <h2 class=\"title is-2 mb-3\">Powerful Features</h2>\n                <div class=\"section-divider\"></div>\n                <p class=\"subtitle is-5 has-text-grey\">\n                    Everything you need to streamline operations and make data-driven decisions\n                </p>\n            </div>\n            \n            <div id=\"features-container\" class=\"columns is-multiline is-centered mt-5\">\n                <!-- Features will be rendered here -->\n            </div>\n        </div>\n    </section>', 'features-section', 'bulma', 200, 1),
('Use Cases Section', '    <!-- Use Cases Section -->\n    <section class=\"section py-6 has-background-light\">\n        <div class=\"container\">\n            <div class=\"has-text-centered mb-6\">\n                <h2 class=\"title is-2 mb-3\">Real-World Use Cases</h2>\n                <div class=\"section-divider\"></div>\n                <p class=\"subtitle is-5 has-text-grey\">\n                    See how NexusAI is transforming industries and workflows\n                </p>\n            </div>\n            \n            <div id=\"use-cases-container\" class=\"columns is-multiline\">\n                <!-- Use cases will be rendered here -->\n            </div>\n        </div>\n    </section>', 'use-cases-section', 'bulma', 300, 1),
('Pricing Section', '    <!-- Pricing Section -->\n    <section class=\"section py-6\">\n        <div class=\"container\">\n            <div class=\"has-text-centered mb-6\">\n                <h2 class=\"title is-2 mb-3\">Simple, Transparent Pricing</h2>\n                <div class=\"section-divider\"></div>\n                <p class=\"subtitle is-5 has-text-grey\">\n                    Choose the plan that fits your needs\n                </p>\n            </div>\n            \n            <div id=\"pricing-container\" class=\"columns is-centered\">\n                <!-- Pricing cards will be rendered here -->\n            </div>\n        </div>\n    </section>', 'pricing-section', 'bulma', 400, 1),
('Testimonials Section', '    <!-- Testimonials Section -->\n    <section class=\"section py-6 has-background-light\">\n        <div class=\"container\">\n            <div class=\"has-text-centered mb-6\">\n                <h2 class=\"title is-2 mb-3\">Trusted by Industry Leaders</h2>\n                <div class=\"section-divider\"></div>\n                <p class=\"subtitle is-5 has-text-grey\">\n                    See what our customers say about NexusAI\n                </p>\n            </div>\n            \n            <div id=\"testimonials-container\" class=\"columns is-multiline\">\n                <!-- Testimonials will be rendered here -->\n            </div>\n        </div>\n    </section>', 'testimonials-section', 'bulma', 500, 1),
('CTA Section', '    <!-- CTA Section -->\n    <section class=\"section py-6 hero-gradient\">\n        <div class=\"container\">\n            <div class=\"has-text-centered\">\n                <h2 class=\"title is-2 has-text-white mb-4\">Ready to Transform Your Workflow?</h2>\n                <p class=\"subtitle is-5 has-text-light mb-5\">\n                    Join 10,000+ teams already using NexusAI to boost productivity\n                </p>\n                <a id=\"cta-btn\" class=\"button is-light is-large has-text-weight-bold\">Get Started Today</a>\n            </div>\n        </div>\n    </section>', 'cta-section', 'bulma', 600, 1);
